-- V31: 补全其余 12 个分类 37 个工具的表单 schema
--
-- 与 V30 同一批工作，拆成两个迁移只是因为单个文件太长不好 review。
-- 幂等条件同样是 `AND form_schema IS NULL`：只填空缺，不动运营改过的内容。

/* ------------------------------ 模特试衣 / AI 换模特 ------------------------------ */

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"clothing","label":"上传服装图","required":true,"hint":"服装平铺图或已有上身图"},{"key":"model","label":"上传模特参考图","required":true,"hint":"目标模特的脸部或全身参考"}],"fields":[{"key":"modelType","type":"select","label":"模特类型","required":true,"options":["女模","男模","童模"]},{"key":"bodyType","type":"select","label":"身材","options":["标准","高挑","微胖","健身"]},{"key":"pose","type":"select","label":"姿态","options":["站立","行走","坐姿","侧身"]},{"key":"scene","type":"select","label":"背景","options":["纯色","影棚","街景","室内"]}],"guide":{"intro":"虚拟模特试穿：给定服装和模特参考，生成上身效果图，衣服的版型、褶皱和图案都按原款还原。","steps":["上传服装图与模特参考","选择模特类型、身材与姿态","提交后生成试穿图"],"tips":["服装图最好平铺正拍，图案方向不会歪","模特参考图正面、光线均匀时相似度最高"]},"credits":{"perImage":2}}' WHERE tool_key = 'virtual-model' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"clothing","label":"上传原图（含模特）","required":true,"hint":"保留服装与商品的原始画面"},{"key":"model","label":"上传目标模特图","required":true,"hint":"要换成的新面孔或新体型"}],"fields":[{"key":"modelAge","type":"select","label":"模特年龄段","options":["18-25","26-35","36-45","45 岁以上"]},{"key":"ethnicity","type":"select","label":"人种特征","options":["亚洲","欧美","非洲","拉美"]},{"key":"expression","type":"select","label":"表情","options":["自然","微笑","冷感"]}],"guide":{"intro":"只换画面里的人，服装、商品和场景全部保留，用来做多地区、多人群的投放素材。","steps":["上传含模特的原图与目标模特图","选择年龄段与人种特征","提交后替换模特形象"],"tips":["原图模特被遮挡少，替换后衔接越自然","同一套服装多生成几个模特，方便做 A/B 测试"]},"credits":{"perImage":2}}' WHERE tool_key = 'ai-model-swap' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"clothing","label":"上传原模特图","required":true,"hint":"身材、服装和场景都取自这张图"},{"key":"model","label":"上传目标面部图","required":true,"hint":"正脸清晰、无遮挡"}],"fields":[{"key":"keepHairstyle","type":"select","label":"发型","options":["保留原发型","使用目标图发型"]},{"key":"skinMatch","type":"select","label":"肤色处理","options":["自动匹配原图光线","保留目标肤色"]},{"key":"blend","type":"select","label":"融合程度","options":["低（轮廓清晰）","中","高（完全融入）"]}],"guide":{"intro":"只换脸：身材、服装、姿势和背景都不动，适合同一组图的模特统一替换。","steps":["上传原模特图与目标面部图","选择发型与肤色处理方式","提交后替换面部"],"tips":["目标图正脸、光照均匀时相似度最高","侧脸替换容易失真，尽量选正脸素材"]},"credits":{"perImage":2}}' WHERE tool_key = 'model-face-swap' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"clothing","label":"上传人物原图","required":true,"hint":"保留身份特征的模特图"},{"key":"model","label":"上传姿态参考图","required":true,"hint":"想要的目标姿势"}],"fields":[{"key":"poseAccuracy","type":"select","label":"姿态还原度","options":["严格跟随","适度调整","仅作参考"]},{"key":"keepOutfit","type":"select","label":"服装处理","options":["保留原服装","使用参考图服装"]},{"key":"note","type":"textarea","label":"补充说明","placeholder":"例如：手部不要遮挡裙摆"}],"guide":{"intro":"把人物迁移到目标姿势，同时保留本人面貌与身上的商品，用于同款多姿势展示。","steps":["上传人物原图与姿态参考图","选择还原度与服装处理方式","提交后生成新姿势"],"tips":["参考图姿势越清晰，关节越不容易出错","还原度调低会更自然，但可能偏离参考动作"]},"credits":{"perImage":2}}' WHERE tool_key = 'model-pose-transfer' AND form_schema IS NULL;

/* ------------------------------ 商品抠图 ------------------------------ */

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"主体与背景有一定对比度更好"}],"fields":[{"key":"edgeMode","type":"select","label":"边缘处理","options":["硬边","柔边","发丝级"]},{"key":"outputBg","type":"select","label":"输出背景","options":["透明","纯白","浅灰"]},{"key":"feather","type":"select","label":"羽化","options":["无","轻微","柔和"]}],"guide":{"intro":"去除背景只留商品主体，边缘按商品类型选择硬边或柔边，输出可直接用于主图或合成。","steps":["上传商品图","选择边缘处理与输出背景","提交后下载抠图结果"],"tips":["毛绒、毛发类选「发丝级」，硬边会切得太生硬","透明输出后续再合成时，记得保留 PNG"]},"credits":{"perImage":1}}' WHERE tool_key = 'image-cutout' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"需要转风格的主体"},{"key":"replacement","label":"上传风格参考图","required":false,"hint":"可选，指定目标艺术风格"}],"fields":[{"key":"styleStrength","type":"select","label":"风格强度","options":["轻微","中等","强烈"]},{"key":"keepSubject","type":"select","label":"主体处理","options":["保留商品细节","允许整体重绘"]},{"key":"palette","type":"select","label":"配色","options":["沿用原图","参考图配色","低饱和","高饱和"]}],"guide":{"intro":"把商品图转成另一种视觉风格（手绘、复古、霓虹等），主体结构保留，画风整体切换。","steps":["上传商品图，可附风格参考","选择风格强度与配色","提交后转换"],"tips":["强度「强烈」会改变材质观感，正式主图慎用","要保留标签文字，强度别超过「中等」"]},"credits":{"perImage":2}}' WHERE tool_key = 'style-transfer' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传原图","required":true,"hint":"需要放大的商品图"}],"fields":[{"key":"scale","type":"select","label":"放大倍数","required":true,"options":["2 倍","4 倍","8 倍"]},{"key":"enhance","type":"select","label":"增强方式","options":["保留原貌","增强细节","超清修复"]},{"key":"denoise","type":"select","label":"降噪","options":["无","轻度","中度"]}],"guide":{"intro":"无损放大商品图，同时补细节、压噪点，用于详情页大图或印刷物料。","steps":["上传原图","选择放大倍数与增强方式","提交后下载高分辨率结果"],"tips":["原图本身糊得太厉害，8 倍会放大瑕疵","印刷用途建议 4 倍以内，边缘更干净"]},"credits":{"perImage":1}}' WHERE tool_key = 'image-upscale' AND form_schema IS NULL;

/* ------------------------------ 鞋子上脚 ------------------------------ */

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"clothing","label":"上传鞋款图","required":true,"hint":"建议侧面或 45 度角"},{"key":"model","label":"上传脚部 / 腿部图","required":true,"hint":"用于匹配肤色与腿部比例"}],"fields":[{"key":"footType","type":"select","label":"脚型","options":["纤细","标准","宽脚"]},{"key":"skinTone","type":"select","label":"肤色","options":["自动匹配","白皙","自然","小麦"]},{"key":"background","type":"select","label":"背景","options":["纯色","地面","街景"]}],"guide":{"intro":"把鞋款自然穿到模特脚上，匹配腿部比例、肤色与地面光影，做出真实上脚效果。","steps":["上传鞋款图与脚部参考图","选择脚型与肤色","选择背景后提交"],"tips":["鞋款侧面图最容易对齐鞋型","有地面时加投影，站立感更强"]},"credits":{"perImage":2}}' WHERE tool_key = 'shoe-on-foot' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传鞋子图","required":true,"hint":"侧面清晰，鞋底纹理可见"},{"key":"model","label":"上传模特全身图","required":false,"hint":"可选，给定腿部与穿搭参考"}],"fields":[{"key":"action","type":"select","label":"动态","options":["行走","奔跑","跳跃","转身"]},{"key":"cameraAngle","type":"select","label":"机位","options":["正面","侧面","俯视","低角度"]},{"key":"scene","type":"select","label":"场景","options":["纯色地面","街道","跑道","室内"]}],"guide":{"intro":"生成鞋类详情页常用的动态展示图：侧身行走、奔跑或起跳，突出鞋型与鞋底结构。","steps":["上传鞋款图，可选附模特全身图","选择动态与机位","提交后生成动态图"],"tips":["详情页首图多用侧面行走，鞋型最完整","低角度机位显腿长，适合短靴"]},"credits":{"perImage":2}}' WHERE tool_key = 'shoe-walking-showcase' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传鞋子图","required":true,"hint":"需要精修的鞋款成片"}],"fields":[{"key":"focus","type":"select","label":"精修重点","options":["鞋面","鞋底","鞋带","鞋标","整体"]},{"key":"enhance","type":"select","label":"强化方向","options":["清晰度","材质质感","色彩准确"]},{"key":"keepShape","type":"select","label":"版型","options":["保持原版型","优化轮廓线条"]}],"guide":{"intro":"强化鞋款的纹理、缝线与材质细节，让皮面、网布、橡胶底各自看起来像真材实料。","steps":["上传鞋款图","选择精修重点与强化方向","提交后输出"],"tips":["鞋标文字精修前先确认拍摄清晰，糊字补不回来","网布类不要过度锐化，容易出摩尔纹"]},"credits":{"perImage":1}}' WHERE tool_key = 'shoe-detail-retouch' AND form_schema IS NULL;

/* ------------------------------ 一键穿搭 / 自定义试衣 ------------------------------ */

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"clothing","label":"上传主单品","required":true,"hint":"上衣或连衣裙等主体"},{"key":"replacement","label":"上传搭配单品","required":false,"hint":"可选，指定下装或配饰"}],"fields":[{"key":"occasion","type":"select","label":"使用场合","required":true,"options":["通勤","休闲","约会","运动","度假"]},{"key":"style","type":"select","label":"风格","options":["简约","甜酷","法式","街头","学院"]},{"key":"season","type":"select","label":"季节","options":["春夏","秋冬","四季"]}],"guide":{"intro":"给定一套服装，自动补齐下装、鞋包和配饰，生成完整的模特上身穿搭图。","steps":["上传主单品，可附指定搭配单品","选择场合与风格","提交后生成整套穿搭"],"tips":["主单品颜色越明确，搭配越不容易跑偏","要控制预算感就选「通勤」或「简约」"]},"credits":{"perImage":2}}' WHERE tool_key = 'one-click-outfit' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传服装图","required":true,"hint":"需要平铺展示的单品"},{"key":"replacement","label":"上传搭配单品","required":false,"hint":"可选，一起摆进画面"}],"fields":[{"key":"layout","type":"select","label":"排布方式","required":true,"options":["网格平铺","自由散落","杂志风"]},{"key":"background","type":"select","label":"底材","options":["白底","浅灰","木纹","布料"]},{"key":"props","type":"chips","label":"点缀","multiple":true,"options":["鞋包","配饰","植物","无道具"]}],"guide":{"intro":"把多件服装组合成一张平铺图，排布整齐、间距均匀，适合做套装和搭配套餐的主图。","steps":["上传服装图，可再上传搭配单品","选择排布方式与底材","提交后生成平铺图"],"tips":["单品数量控制在 3-5 件，画面更清爽","木纹与布料底材更有质感，纯白最通用"]},"credits":{"perImage":2}}' WHERE tool_key = 'outfit-flatlay' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"clothing","label":"上传服装图","required":true,"hint":"整体或单品都可以"}],"fields":[{"key":"targetColor","type":"select","label":"目标颜色","required":true,"options":["米白","驼色","藏蓝","墨绿","酒红","黑色"]},{"key":"partScope","type":"select","label":"改色范围","options":["全部","仅上装","仅下装","仅配饰"]},{"key":"keepTexture","type":"select","label":"纹理处理","options":["保留面料纹理","整体重绘"]}],"guide":{"intro":"把整套服装或某一件换成另一个配色，同时保留面料纹理与褶皱，用来快速扩充色卡。","steps":["上传服装图","选择目标颜色与改色范围","提交后输出新配色"],"tips":["深色改浅色容易丢层次，建议一档一档改","清晰度允许的话，多色一起生成对比更直观"]},"credits":{"perImage":2}}' WHERE tool_key = 'outfit-color-change' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"clothing","label":"上传服装图","required":true,"hint":"平铺或挂拍，版型清楚"},{"key":"model","label":"上传模特参考图","required":true,"hint":"目标身材与身高参考"}],"fields":[{"key":"fitLevel","type":"select","label":"合身程度","options":["修身","标准","宽松"]},{"key":"heightAdjust","type":"select","label":"身高比例","options":["不调整","微调","明显调整"]},{"key":"note","type":"textarea","label":"补充说明","placeholder":"例如：模特 165cm，穿 M 码"}],"guide":{"intro":"按模特身材调整服装比例，解决「平铺看着好、上身不合身」的问题。","steps":["上传服装图与模特参考","选择合身程度与身高比例","提交后生成上身效果"],"tips":["写清模特身高体重，比例判断更准","宽松款不要选「修身」，会破坏设计意图"]},"credits":{"perImage":2}}' WHERE tool_key = 'custom-fit' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"clothing","label":"上传服装图","required":true,"hint":"需要体现尺码感的款式"}],"fields":[{"key":"targetSize","type":"select","label":"目标尺码","required":true,"options":["XS","S","M","L","XL","XXL"]},{"key":"fit","type":"select","label":"版型","options":["修身","标准","宽松"]},{"key":"keepPattern","type":"select","label":"图案处理","options":["保留原图案","需重排图案"]}],"guide":{"intro":"调整服装在画面中的尺码感与松量，展示同一款从紧到松的差别，不用每个码都单独拍。","steps":["上传服装图","选择目标尺码与版型","提交后输出"],"tips":["格纹、条纹改松量时选「需重排图案」","尺码跨度别超过两档，否则版型会失真"]},"credits":{"perImage":2}}' WHERE tool_key = 'garment-size-adjust' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"clothing","label":"上传服装图","required":true,"hint":"需要展示版型细节的款式"},{"key":"model","label":"上传模特图","required":true,"hint":"上身参考"}],"fields":[{"key":"detailFocus","type":"select","label":"细节重点","options":["领口","袖口","腰线","褶皱","整体版型"]},{"key":"wrinkleLevel","type":"select","label":"褶皱程度","options":["自然","较少","较多"]},{"key":"note","type":"textarea","label":"补充说明","placeholder":"例如：突出面料垂坠感"}],"guide":{"intro":"生成服装在真实模特身上的细节特写，领口、腰线、褶皱都能单独强调。","steps":["上传服装图与模特图","选择细节重点与褶皱程度","提交后生成特写"],"tips":["丝绸、雪纺类把褶皱调「较多」，垂坠感更明显","领口细节适合做详情页第二屏"]},"credits":{"perImage":2}}' WHERE tool_key = 'garment-detail-wear' AND form_schema IS NULL;

/* ------------------------------ 穿戴图生成 ------------------------------ */

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传首饰图","required":true,"hint":"白底正拍，细节清晰"},{"key":"model","label":"上传佩戴部位图","required":true,"hint":"颈部、耳部或手部特写"}],"fields":[{"key":"bodyPart","type":"select","label":"佩戴部位","required":true,"options":["颈部","耳部","手腕","手指","发际"]},{"key":"skinTone","type":"select","label":"肤色","options":["自动匹配","白皙","自然","小麦"]},{"key":"lighting","type":"select","label":"光线","options":["自然光","棚拍","暖光"]}],"guide":{"intro":"把首饰戴到指定部位，匹配肤色、光线与皮肤质感，让金属和宝石的反光看起来真实。","steps":["上传首饰图与佩戴部位图","选择佩戴部位与肤色","提交后生成佩戴图"],"tips":["金属类首饰建议棚拍，高光更干净","耳饰要用正面耳部图，侧面容易变形"]},"credits":{"perImage":2}}' WHERE tool_key = 'jewelry-wear' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传腕表图","required":true,"hint":"表盘正面清晰"},{"key":"model","label":"上传手腕图","required":true,"hint":"用于匹配手腕粗细与肤色"}],"fields":[{"key":"wristType","type":"select","label":"手腕粗细","options":["纤细","标准","粗壮"]},{"key":"strapAdjust","type":"select","label":"表带松紧","options":["自动","收紧","放松"]},{"key":"angle","type":"select","label":"拍摄角度","options":["正面","侧面","俯视"]}],"guide":{"intro":"生成腕表、手链的手部佩戴图，表盘比例与表带松紧都会按手腕粗细调整。","steps":["上传腕表图与手腕图","选择手腕粗细与表带松紧","提交后生成佩戴图"],"tips":["表盘正面拍摄、无反光，贴合后最清晰","手腕图带一点环境（袖子、桌面）更自然"]},"credits":{"perImage":2}}' WHERE tool_key = 'watch-wear' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传箱包图","required":true,"hint":"正面或 45 度角，结构清楚"},{"key":"model","label":"上传模特图","required":true,"hint":"全身或半身，用于匹配肩背比例"}],"fields":[{"key":"carryStyle","type":"select","label":"背法","required":true,"options":["手提","单肩","斜挎","双肩"]},{"key":"scene","type":"select","label":"场景","options":["街景","室内","影棚","咖啡店"]},{"key":"modelType","type":"select","label":"模特类型","options":["女模","男模"]}],"guide":{"intro":"生成箱包的上肩、手提或斜挎佩戴效果，包体比例随模特身高与背法自动调整。","steps":["上传箱包图与模特图","选择背法与场景","提交后生成佩戴图"],"tips":["斜挎要注意包带长度，模特身高写清更准","街景背景最贴近真实使用场景"]},"credits":{"perImage":2}}' WHERE tool_key = 'bag-wear' AND form_schema IS NULL;

/* ------------------------------ 小红书风格 ------------------------------ */

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"主体清晰，便于排版"}],"fields":[{"key":"coverStyle","type":"select","label":"封面色调","required":true,"options":["清新","高级感","拼图","大字标题"]},{"key":"textSpace","type":"select","label":"文字留白","options":["顶部留白","底部留白","居中留白"]},{"key":"palette","type":"select","label":"配色","options":["奶油白","莫兰迪","高饱和","黑白"]}],"guide":{"intro":"生成适合小红书封面的商品图：主体偏一侧、留出标题位，色调偏清新或高级。","steps":["上传商品图","选择封面色调与文字留白位置","提交后生成封面"],"tips":["封面标题建议不超过 8 个字，留白才够用","3:4 竖图信息流曝光更好"]},"credits":{"perImage":2}}' WHERE tool_key = 'xhs-cover' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"生活用品、食品、美妆最出片"}],"fields":[{"key":"scene","type":"select","label":"生活场景","required":true,"options":["卧室","餐桌","咖啡店","书桌","阳台"]},{"key":"mood","type":"select","label":"氛围","options":["松弛","治愈","精致","元气"]},{"key":"props","type":"chips","label":"点缀道具","multiple":true,"options":["咖啡杯","书本","绿植","布艺","无道具"]}],"guide":{"intro":"把商品放进真实生活场景里，带一点杂乱和人间气，做种草内容的背景图。","steps":["上传商品图","选择生活场景与氛围","提交后生成场景图"],"tips":["别追求影棚级干净，稍微生活化更有点击率","暖色道具配「治愈」，冷色配「精致」"]},"credits":{"perImage":2}}' WHERE tool_key = 'xhs-lifestyle' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"需要做成笔记配图的产品"}],"fields":[{"key":"layout","type":"select","label":"版式","required":true,"options":["单图","拼图","带标签"]},{"key":"annotation","type":"select","label":"标注方式","options":["无","箭头标注","文字标签"]},{"key":"palette","type":"select","label":"配色","options":["奶油风","清新绿","暖橘","极简白"]}],"guide":{"intro":"生成带「使用感受」气质的产品图：加上标签、箭头或留白，像真实用户拍的笔记配图。","steps":["上传商品图","选择版式与标注方式","提交后生成配图"],"tips":["标注不要超过三处，重点才突出","拼图版式适合一次展示多个角度"]},"credits":{"perImage":2}}' WHERE tool_key = 'xhs-product-note' AND form_schema IS NULL;

/* ------------------------------ 产品精修 / 主图优化 ------------------------------ */

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"需要整体精修的成片"}],"fields":[{"key":"focus","type":"select","label":"精修重点","options":["整体","材质","细节","瑕疵修复"]},{"key":"strength","type":"select","label":"力度","options":["轻度","标准","强修"]},{"key":"keepColor","type":"select","label":"色彩","options":["保留原色","适度校正"]}],"guide":{"intro":"统一修一遍商品图的光线、颜色、材质和清晰度，让同批次图片看起来是同一台相机拍的。","steps":["上传商品图","选择精修重点与力度","提交后输出"],"tips":["同批次图片建议用同一套参数，风格才统一","「强修」会抹掉细小纹理，皮具类慎用"]},"credits":{"perImage":1}}' WHERE tool_key = 'product-retouch' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"存在色差或白平衡问题的图"}],"fields":[{"key":"targetMode","type":"select","label":"校正目标","options":["还原真实","提升鲜艳","统一色调"]},{"key":"colorTemp","type":"select","label":"色温","options":["自动","偏暖","偏冷","中性"]},{"key":"saturation","type":"select","label":"饱和度","options":["不加","轻微","明显"]}],"guide":{"intro":"修正色差与白平衡：把偏黄、偏蓝或发灰的商品图拉回真实颜色，也可以统一成店铺色调。","steps":["上传商品图","选择校正目标与色温","提交后输出"],"tips":["要还原真实颜色，最好在原图里保留一个中性灰参照","同一店铺统一色温，详情页观感更连贯"]},"credits":{"perImage":1}}' WHERE tool_key = 'product-color-correct' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"细节发糊或边缘发虚的图"}],"fields":[{"key":"detailArea","type":"select","label":"增强区域","options":["纹理","文字","缝线","logo","全部"]},{"key":"sharpness","type":"select","label":"锐度","options":["轻微","标准","锐利"]},{"key":"denoise","type":"select","label":"降噪","options":["无","轻度","中度"]}],"guide":{"intro":"增强商品的纹理、边缘与文字清晰度，用于详情页的局部特写。","steps":["上传商品图","选择增强区域与锐度","提交后输出"],"tips":["文字和 logo 精修前先确认原图没糊，糊了补不回来","锐利加中度降噪，噪点不会跟着被放大"]},"credits":{"perImage":1}}' WHERE tool_key = 'product-detail-enhance' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"建议主体完整、背景干净"}],"fields":[{"key":"platform","type":"select","label":"目标平台","required":true,"options":["淘宝","天猫","京东","拼多多","抖音商城"]},{"key":"ratio","type":"select","label":"画幅比例","options":["1:1","3:4","4:3","16:9"]},{"key":"focus","type":"select","label":"优化重点","options":["主体占比","留白规范","背景干净","整体质感"]}],"guide":{"intro":"按电商平台的主图规范生成成片：画幅、主体占比、留白都对齐平台要求，避免被判违规。","steps":["上传商品图","选择目标平台与画幅","提交后生成主图"],"tips":["1:1 是绝大多数平台的首图要求","主体占比建议 70% 上下，太满容易被裁"]},"credits":{"perImage":2}}' WHERE tool_key = 'platform-main-image' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"自动抠图后换成白底"}],"fields":[{"key":"bgWhite","type":"select","label":"底色","required":true,"options":["纯白","浅灰","透明"]},{"key":"shadow","type":"select","label":"阴影","options":["无","接触阴影","柔和投影"]},{"key":"margin","type":"select","label":"留白","options":["紧凑","标准","留白充足"]}],"guide":{"intro":"生成标准白底主图，边缘干净、留白规范，可选保留一点接触阴影避免「飘着」。","steps":["上传商品图","选择底色、阴影与留白","提交后输出"],"tips":["平台审核一般要求纯白（255,255,255）","加一点接触阴影，商品看起来是放在台面上的"]},"credits":{"perImage":1}}' WHERE tool_key = 'white-background-main' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"主体需要挪位置的成片"}],"fields":[{"key":"layout","type":"select","label":"版式","required":true,"options":["居中","对角","九宫格","杂志感"]},{"key":"textSpace","type":"select","label":"卖点文字位","options":["无","顶部","底部","左侧","右侧"]},{"key":"props","type":"select","label":"装饰元素","options":["无","色块","几何图形","标签贴纸"]}],"guide":{"intro":"调整主图里商品的位置和留白，给卖点文字腾出地方，之后在详情页加上文案即可。","steps":["上传商品图","选择版式与文字位","提交后输出"],"tips":["要加长文案就选「留白充足」的版式","标签贴纸别压在商品主体上"]},"credits":{"perImage":1}}' WHERE tool_key = 'main-image-layout' AND form_schema IS NULL;

/* ------------------------------ 场景合成 / 服装搭配 / 其他 ------------------------------ */

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"主体商品，建议先抠好图"},{"key":"background","label":"上传场景图","required":true,"hint":"目标商业场景"}],"fields":[{"key":"perspective","type":"select","label":"透视匹配","options":["自动匹配","平视","俯视","仰视"]},{"key":"shadow","type":"select","label":"投影","options":["自动生成","保留原投影","无投影"]},{"key":"colorMatch","type":"select","label":"色调统一","options":["自动匹配场景","保持商品原色"]}],"guide":{"intro":"把多个商品素材合进同一张场景图，透视、投影和色调一起对齐，看起来像一起拍的。","steps":["上传商品图与场景图","选择透视与投影方式","提交后合成"],"tips":["商品图先抠成透明底，合成边缘最干净","同一场景里放多个商品时，一个一个有层次地摆"]},"credits":{"perImage":2}}' WHERE tool_key = 'scene-composition' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"需要放进节日场景的商品"},{"key":"background","label":"上传节日素材图","required":false,"hint":"可选，指定装饰元素"}],"fields":[{"key":"festival","type":"chips","label":"节日节点","multiple":true,"options":["春节","情人节","618","中秋","双11","圣诞","年货节"]},{"key":"paletteColor","type":"select","label":"主色调","options":["红金","粉紫","清新绿","蓝白"]},{"key":"props","type":"chips","label":"节庆元素","multiple":true,"options":["灯笼","礼盒","雪花","花瓣","彩带","无"]}],"guide":{"intro":"按节日节点生成促销场景：配色、装饰元素和氛围一起换，一套商品图能复用一整年的活动。","steps":["上传商品图，可选附节日素材","勾选节日与节庆元素","提交后生成场景"],"tips":["一次只选一个节日，元素混搭会显得乱","红金配色最通用，春节与双11 都能用"]},"credits":{"perImage":2}}' WHERE tool_key = 'festival-scene' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"需要放进生活方式的商品"},{"key":"background","label":"上传场景参考图","required":false,"hint":"可选，指定具体生活场景"}],"fields":[{"key":"lifestyle","type":"select","label":"生活方式","required":true,"options":["咖啡时光","阅读","运动","旅行","居家"]},{"key":"mood","type":"select","label":"氛围","options":["松弛","治愈","精致","元气"]},{"key":"props","type":"chips","label":"道具","multiple":true,"options":["咖啡杯","书本","绿植","毯子","无道具"]}],"guide":{"intro":"生成真实自然的家居、户外或生活方式场景，让商品融进一个正在发生的生活片段。","steps":["上传商品图，可附场景参考","选择生活方式与氛围","提交后生成场景图"],"tips":["场景里出现人手或生活痕迹，真实感更强","同系列商品用同一套生活方式，内容更成体系"]},"credits":{"perImage":2}}' WHERE tool_key = 'lifestyle-scene' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"clothing","label":"上传主商品图","required":true,"hint":"需要配穿搭的那一件"},{"key":"model","label":"上传模特图","required":false,"hint":"可选，指定上身模特"}],"fields":[{"key":"occasion","type":"select","label":"场合","required":true,"options":["通勤","休闲","约会","运动","度假"]},{"key":"style","type":"select","label":"风格","options":["简约","甜酷","法式","街头","学院"]},{"key":"palette","type":"select","label":"配色倾向","options":["同色系","中性色","撞色"]}],"guide":{"intro":"按商品风格推荐并生成完整穿搭：下装、外套、鞋包一起配好，直接出模特上身图。","steps":["上传主商品图，可选附模特图","选择场合与风格","提交后生成整套搭配"],"tips":["先定场合再定风格，搭配逻辑更顺","同色系最不容易出错，撞色适合做视觉冲击款"]},"credits":{"perImage":2}}' WHERE tool_key = 'outfit-matching' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"clothing","label":"上传服装图","required":true,"hint":"用于提取主色"}],"fields":[{"key":"scheme","type":"select","label":"配色方案","required":true,"options":["同色系","邻近色","对比色","中性色"]},{"key":"mainColor","type":"text","label":"主色","placeholder":"例如：雾霾蓝，留空则由模型提取"},{"key":"accentColor","type":"text","label":"点缀色","placeholder":"例如：米白"}],"guide":{"intro":"提取商品主色并生成协调的上下装配色，避免自己搭配时颜色打架。","steps":["上传服装图","选择配色方案，可指定主色与点缀色","提交后生成配色穿搭"],"tips":["主色留空时模型会自动取色，适合先看效果","对比色方案建议点缀色只占小面积"]},"credits":{"perImage":2}}' WHERE tool_key = 'outfit-color-matching' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"clothing","label":"上传已有穿搭图","required":true,"hint":"需要补配饰的服装或模特图"},{"key":"replacement","label":"上传配饰图","required":false,"hint":"可选，指定要加的鞋包或配饰"}],"fields":[{"key":"category","type":"chips","label":"配饰类目","multiple":true,"options":["鞋","包","首饰","帽子","腰带","眼镜"]},{"key":"style","type":"select","label":"风格","options":["简约","甜酷","法式","街头","学院"]},{"key":"note","type":"textarea","label":"补充说明","placeholder":"例如：配一双乐福鞋，不要高跟"}],"guide":{"intro":"给已有穿搭自动补上合适的鞋包与配饰，整套造型更完整。","steps":["上传穿搭图，可附指定配饰","勾选配饰类目与风格","提交后生成搭配"],"tips":["一次加一到两类配饰，画面不会太满","指定配饰图时，视角与穿搭图接近更好贴"]},"credits":{"perImage":2}}' WHERE tool_key = 'accessory-matching' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"支持一次上传多张，批量处理"}],"fields":[{"key":"task","type":"chips","label":"处理项","required":true,"multiple":true,"options":["抠图","换背景","精修","调色","加阴影"]},{"key":"outputSize","type":"select","label":"输出尺寸","options":["1024x1024","1536x1024","1024x1536","按原图"]},{"key":"note","type":"textarea","label":"补充说明","placeholder":"例如：统一白底、主体占 70%"}],"guide":{"intro":"批量统一多张商品图的背景、尺寸、光线和风格，一次处理整个 SKU 列表。","steps":["一次上传多张商品图","勾选处理项与输出尺寸","提交后逐张输出"],"tips":["同批图片尽量用相近的原始尺寸，输出更整齐","处理项别一次全勾，先跑一批看效果"]},"credits":{"perImage":1}}' WHERE tool_key = 'batch-commerce' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"海报主体商品"},{"key":"replacement","label":"上传海报背景 / 素材","required":false,"hint":"可选，指定版式素材"}],"fields":[{"key":"layout","type":"select","label":"版式","required":true,"options":["主图居中","左右分栏","上下分栏","自由"]},{"key":"copySpace","type":"select","label":"文案区域","options":["顶部","底部","左侧","右侧"]},{"key":"palette","type":"select","label":"配色","options":["红金","蓝白","渐变科技","莫兰迪"]}],"guide":{"intro":"生成适合活动页与社媒投放的商品海报构图：主体位置、文案区和配色一次到位。","steps":["上传商品图，可附版式素材","选择版式与文案区域","提交后生成海报底图"],"tips":["文案区留白要足，后期加字才不挤","社媒投放建议用上下分栏，手机上看更完整"]},"credits":{"perImage":2}}' WHERE tool_key = 'poster-layout' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"需要清理的成片或素材"}],"fields":[{"key":"cleanTarget","type":"chips","label":"清理目标","required":true,"multiple":true,"options":["杂物","水印","多余文字","瑕疵","背景杂色","反光"]},{"key":"keepSubject","type":"select","label":"主体保护","options":["严格保留","允许微调"]},{"key":"outputBg","type":"select","label":"处理后背景","options":["保留原背景","纯白","透明"]}],"guide":{"intro":"清掉商品图里的水印、杂物和干扰元素，主体与材质完全保留。","steps":["上传商品图","勾选要清理的目标","提交后输出干净成片"],"tips":["水印压在商品主体上时，选「允许微调」补得更自然","一次只清一类问题，效果比全勾更好"]},"credits":{"perImage":1}}' WHERE tool_key = 'commerce-cleanup' AND form_schema IS NULL;
